import numpy as np
def fit_predict(train, inputs, seed):
    return [float(np.median(train['y']))]*len(inputs['X'])

from sklearn.ensemble import HistGradientBoostingRegressor
def fit_predict(train, inputs, seed):
    model=HistGradientBoostingRegressor(max_iter=250,learning_rate=0.08,max_leaf_nodes=31,l2_regularization=1,random_state=1729)
    model.fit(train['X'],train['y'])
    return model.predict(inputs['X']).tolist()
